    # opposite edge, retaining all existing cells.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    coords = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5:
                coords.setdefault(grid[r][c], []).append((r,c))
    for color, pts in coords.items():
        if len(pts) < 2: continue
