        # from endpoints, where possible.
        for r,c in pts:
            for dr,dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                if (r-dr,c-dc) in pts and (r+dr,c+dc) not in pts:
                    rr,cc=r+dr,c+dc
                    while 0<=rr<h and 0<=cc<w and out[rr][cc] in (5,color):
                        out[rr][cc]=color
                        rr+=dr;cc+=dc
    return out

